// Define symbols to analyze
const symbols = ['EURUSD', 'GBPUSD', 'USDJPY'];
const timeframe = 'M30';

return symbols.map(symbol => ({
  json: {
    symbol,
    timeframe,
    marketSummary: `Current market conditions for ${symbol}. Price action showing consolidation. Volume is moderate.`
  }
}));

// Build RAG context and Grok prompt
const symbol = $('Set Trading Symbols').item.json.symbol;
const timeframe = $('Set Trading Symbols').item.json.timeframe;
const marketSummary = $('Set Trading Symbols').item.json.marketSummary;

const historicalTrades = $input.all();
let ragContext = 'No historical trades available.';

if (historicalTrades.length > 0) {
  const contextLines = historicalTrades.map((item, idx) => {
    const data = item.json;
    const outcome = data.is_win === true ? '✓ WIN' : 
                    data.is_win === false ? '✗ LOSS' : '⏳ PENDING';
    return `${idx + 1}. ${data.direction} - ${outcome} (Confidence: ${(data.confidence * 100).toFixed(0)}%)`;
  });
  ragContext = contextLines.join('\n');
}

const prompt = `You are a forex trading analyst. Analyze ${symbol} and provide a recommendation.

Market: ${marketSummary}

Recent trades:
${ragContext}

Respond with ONLY this JSON (no markdown):
{
  "symbol": "${symbol}",
  "timeframe": "${timeframe}",
  "direction": "LONG|SHORT|FLAT",
  "entry_price": 1.12345,
  "stop_loss": 1.12000,
  "take_profit": 1.13000,
  "confidence": 0.75,
  "rationale": "Brief explanation",
  "notes": "Optional notes"
}`;

return {
  json: {
    symbol,
    timeframe,
    prompt,
    ragCount: historicalTrades.length
  }
};

