// Parse Grok response
let content = $json.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('No content in Grok response');
}

// Clean markdown
content = content.trim().replace(/```json\n?/g, '').replace(/```\n?/g, '');

// Parse JSON
const trade = JSON.parse(content);

// Validate
if (!trade.symbol || !trade.confidence || !trade.direction) {
  throw new Error('Invalid trade response');
}

if (trade.confidence < 0 || trade.confidence > 1) {
  throw new Error('Invalid confidence value');
}

return { json: trade };

// Build email HTML
const trade = $('Parse & Validate Response').item.json;
const emoji = trade.direction === 'LONG' ? '📈' : trade.direction === 'SHORT' ? '📉' : '⏸️';
const conf = (trade.confidence * 100).toFixed(1);

const risk = Math.abs(trade.entry_price - trade.stop_loss);
const reward = Math.abs(trade.take_profit - trade.entry_price);
const rr = risk > 0 ? `1:${(reward/risk).toFixed(2)}` : 'N/A';

const html = `
<!DOCTYPE html>
<html>
<head>
<style>
  body { font-family: Arial; background: #f4f4f4; padding: 20px; }
  .container { background: white; border-radius: 8px; padding: 20px; max-width: 600px; margin: 0 auto; }
  .header { background: #1a73e8; color: white; padding: 15px; border-radius: 5px; text-align: center; }
  .info { margin: 20px 0; }
  .row { padding: 10px 0; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; }
  .label { font-weight: bold; }
</style>
</head>
<body>
<div class="container">
  <div class="header"><h2>${emoji} Trade Signal: ${trade.symbol}</h2></div>
  <div class="info">
    <div class="row"><span class="label">Direction:</span><span>${trade.direction}</span></div>
    <div class="row"><span class="label">Entry:</span><span>${trade.entry_price.toFixed(5)}</span></div>
    <div class="row"><span class="label">Stop Loss:</span><span>${trade.stop_loss.toFixed(5)}</span></div>
    <div class="row"><span class="label">Take Profit:</span><span>${trade.take_profit.toFixed(5)}</span></div>
    <div class="row"><span class="label">R/R:</span><span>${rr}</span></div>
    <div class="row"><span class="label">Confidence:</span><span style="font-size:18px;font-weight:bold;color:#1a73e8">${conf}%</span></div>
  </div>
  <div style="background:#f8f9fa;padding:15px;border-left:4px solid #1a73e8;margin:15px 0;">
    <strong>Analysis:</strong><br>${trade.rationale}
    ${trade.notes ? `<br><br><strong>Notes:</strong> ${trade.notes}` : ''}
  </div>
  <p style="text-align:center;color:#888;font-size:12px;">${new Date().toLocaleString()}</p>
</div>
</body>
</html>
`;

return {
  json: {
    subject: `🚨 Trade Signal: ${trade.symbol} ${trade.direction}`,
    html: html
  }
};
